INSERT INTO `products` (`slug`, `category_id`, `sort_order`, `name`, `description`, `full_description`, `product_line`, `material`, `img`, `img_v`, `safety_class_raw`, `is_new`, `hidden`, `spec_json`) VALUES
('dune-rock-green','footwear',0,'Dune Rock Green','High-cut safety trainer with anti-abrasion mesh upper and Ultra Rebound technology midsole. BOA-style quick-lace closure system.','<p><strong>Work high shoes from the Dune line</strong> made with a <strong>special NHP (High Performance Nylon) compound </strong>composed of EVA, with the specific function of <strong>cushioning impacts</strong> on the foot. The distinctive feature of Dune safety shoes is their<strong> highly stable sole</strong> with excellent grip, which guarantees greater safety on all types of terrain.</p><p>These safety shoes also feature an <strong>abrasion-resistant upper</strong>, rubber reinforcement on the toe and<strong> TPU reinforcement</strong> <strong>in areas of high wear</strong> to ensure protection and durability. <strong>The tongue with bellows </strong>limits the passage of dust inside the shoe.</p><p>Dune Rock Green work high shoes are the <strong>ideal solution for those looking for a comfortable and lightweight work shoe </strong>that offers comfort, cushioning and protection at the same time.</p><h3>TECHNICAL SPECIFICATIONS</h3><ul><li>tongue with anti-dust bellows</li><li>abrasion-resistant upper</li><li>rubber reinforcement on the toe</li><li>TPU reinforcement in areas of wear</li><li>cushioned NHP midsole</li><li>high stability and grip sole</li></ul><h3>MATERIALS</h3><ul><li><strong>Upper:</strong> Abrasion-resistant mesh</li><li><strong>Toe cap: </strong>Carbon fibre</li><li><strong>Anti-perforation insole:</strong> High Flex</li><li><strong>Midsole: </strong>NHP Ultra Rebound</li><li><strong>Outsole:</strong> Rubber</li></ul>','DUNE Ultra Rebound Technology','Anti-Abrasion Mesh','assets/img/products/dune-rock-green.webp','20260723',NULL,0,0,'{"materialComposition":null,"weightGrams":560,"fit":"Relaxed","toeCap":"Composite (NHP)","midsole":null,"sole":"NHP Rubber","gender":"Unisex","season":null,"pageRef":66}'),
('dune-rock-black','footwear',1,'Dune Rock Black','High-cut safety trainer with anti-abrasion mesh upper and Ultra Rebound technology. BOA-style rotary closure for precise fit adjustment.','<p>Dune Rock Black work high shoes are designed to guarantee <strong>cushioning, comfort and safety</strong> even in the most difficult working conditions. Made with a special<strong> EVA-based NHP (High Performance Nylon) compound</strong>, the safety shoes in the Dune line are designed to effectively cushion impacts on the foot, offering a feeling of lightness even after many hours of use.</p><p>These work high shoes stand out for their <strong>quick and secure fastening system</strong>, which allows you to put on and take off the shoe in seconds, while ensuring a stable and reliable fit.</p><p><strong>The high-stability sole</strong> guarantees optimal grip and abrasion resistance for greater safety on any type of terrain, while the <strong>abrasion-resistant upper</strong>, rubber reinforcement on the toe and <strong>TPU reinforcement</strong> in the most stressed areas ensure extra protection and superior durability over time.</p><h3>TECHNICAL SPECIFICATIONS</h3><ul><li>tongue with anti-dust bellows</li><li>quick and safe fastening system</li><li>abrasion-resistant upper</li><li>rubber reinforcement on the toe</li><li>TPU reinforcements at major wear points</li><li>cushioned NHP midsole</li><li>high stability and grip sole</li></ul><h3>MATERIALS</h3><ul><li><strong>Upper:</strong> Abrasion-resistant mesh</li><li><strong>Toe cap:</strong> Carbon fibre</li><li><strong>Anti-perforation insole:</strong> High Flex</li><li><strong>Midsole:</strong> NHP Ultra Rebound</li><li><strong>Outsole:</strong> Rubber</li></ul>','DUNE Ultra Rebound Technology','Anti-Abrasion Mesh','assets/img/products/dune-rock-black-2.webp','1784995764855',NULL,0,0,'{"materialComposition":null,"weightGrams":560,"fit":"Relaxed","toeCap":"Composite (NHP)","midsole":null,"sole":"NHP Rubber","gender":"Unisex","season":null,"pageRef":66}'),
('dune-jaq','footwear',2,'Dune JAQ','Low-cut ESD safety trainer with Jaquard + TPU upper construction. Available in multiple colours and extended sizes including 36–46.','<p>The <strong>new Dune Jaq work shoes</strong> are the ideal solution for those looking for a comfortable and lightweight shoe, which immediately feels<strong> elastic, soft and cushioning,</strong> thanks to the <strong>innovative NHP midsole</strong> that develops an <strong>Ultra Rebound effect</strong> during walking.</p><p>The special NHP (Nylon High Performances) compound made of EVA, with which the midsole and the footbed of the Dune shoes are made, has been specially designed to ensure a high level of cushioning, flexibility and maximum comfort.</p><p>Dune Jaq safety shoes are <strong>ESD certified for electrostatic dissipation</strong> and are designed for those who work in working environments with electronically controlled machines, flammable liquids and gases, microchip, production of electrical components and in several laboratories at risk. In addition to the new midsole, the work shoes of the new line Kapriol Dune are equipped with a <strong>resistant non-slip rubber outsole high-grip</strong>, the carbon fiber toe and the anti-puncture sole high flexibility.</p><p>Dune Jaq safety shoes are <strong>available in four colours:</strong> yellow, green, grey and the <strong>new pink colour.</strong></p><h3>TECHNICAL SPECIFICATIONS</h3><ul><li>static discharge function</li><li>Padding on the heel and malleolus</li><li>padded tongue</li><li>Breathable and elastic upper with TPU reinforcements</li><li>rubber reinforcement on the toe</li><li>Weight: 450 gr. (tg. 42)</li><li>EN ISO 20345: 2022</li></ul><h3>Materials</h3><ul><li>Upper: Jauqard and TPU</li><li>Toe: Carbon fibre</li><li>Insole: NHP Tech</li><li>Anti-perforation insole: High Flex PS</li><li>Midsole: NHP Ultra Rebound</li><li>Sole: rubber sole</li></ul>','DUNE Ultra Rebound Technology','Jaquard + TPU','assets/img/products/dune-jaq.webp','20260723',NULL,0,0,'{"materialComposition":null,"weightGrams":450,"fit":"Relaxed","toeCap":"Composite (NHP)","midsole":null,"sole":"NHP Rubber","gender":"Unisex","season":null,"newSizes":true,"pageRef":66}'),
('dune-smesh','footwear',3,'Dune Smesh','Low-cut safety runner with strong mesh + TPU upper. Available in three colourways with ESD-free HRO certification.','<p>The <strong>safety shoes Dune Smesh of the new line of work shoes</strong> <strong>- Ultra Rebound Technology,</strong> are made with upper in mesh fabric and reinforcements in TPU that guarantees flexibility, breathability and abrasion resistance. In addition to the S3S-FO-SR certifications, the Dune Smesh work shoes are <strong>HRO certified </strong>for <strong>protection in high temperature environments</strong>, thanks to the special rubber sole that can withstand heat <strong>up to a maximum of 300°</strong>.</p><p>The light work shoes of the new line Dune give an immediate feeling of <strong>elasticity, softness and cushioning</strong>, generated by the <strong>Ultra Rebound effect </strong>that develops during walking. Thanks to the <strong>special NHP</strong> (Nylon High Performances) compound composed of EVA, midsole and footbed, the new safety shoes guarantee a<strong> high cushioning</strong>, reducing the possibility of damage to joints and muscles for prolonged use.</p><p>The Dune Smesh work shoes are <strong>available in three different color</strong> variations with yellow, green or orange details.</p><h3>TECHNICAL SPECIFICATIONS</h3><ul><li>Sole suitable for high temperature environments (300°C -60&quot;)</li><li>Padding on the heel and malleolus</li><li>padded tongue</li><li>Flexible and breathable abrasion resistant upper</li><li>rubber reinforcement on the toe</li><li>Weight: 480 gr. (tg. 42)</li><li>EN ISO 20345: 2022</li></ul><h3>Materials</h3><ul><li>Upper: Strong Mesh and TPU</li><li>Toe: Carbon fibre</li><li>Insole: NHP Tech</li><li>Anti-perforation insole: High Flex PS</li><li>Midsole: NHP Ultra Rebound</li><li>Sole: rubber sole</li></ul>','DUNE Ultra Rebound Technology','Strong Mesh + TPU','assets/img/products/dune-smesh.webp','20260723',NULL,0,0,'{"materialComposition":null,"weightGrams":480,"fit":"Relaxed","toeCap":"Composite (NHP)","midsole":null,"sole":"NHP Rubber","gender":"Unisex","season":null,"pageRef":66}'),
('dune-stone','footwear',4,'Dune Stone','High-cut safety trekking boot with nubuck upper. S7S rated with cold insulation (CI), waterproof (WR) and slip resistance.','<p>Dune Stone work high shoes offer <strong>maximum stability and grip on all types of terrain</strong> thanks to their V-shaped sole, designed to ensure optimal traction even on slippery surfaces. The special <strong>EVA-based NHP (High Performance Nylon) midsole</strong> makes the shoes <strong>elastic and lightweight,</strong> cushioning impacts on the foot during work.</p><p>Featuring a <strong>durable nubuck upper,</strong> these work high shoes are ideal for harsh environments, thanks to the <strong>dust-proof gusseted tongue,</strong> which prevents debris from entering, and the rubber toe cap reinforcement, which increases protection in the most exposed areas.</p><p><strong>S7S FO SR HRO CI </strong>certified, Dune Stone safety shoes combine safety, durability and comfort in every work situation.</p><h3>TECHNICAL SPECIFICATIONS</h3><ul><li>tongue with anti-dust bellows</li><li>rubber reinforcement on the toe</li><li>cushioned NHP midsole</li><li>high stability and grip sole</li></ul><h3>MATERIALS</h3><ul><li><strong>Upper:</strong> Abrasion-resistant mesh</li><li><strong>Toe cap: </strong>Carbon fibre</li><li><strong>Anti-perforation insole: </strong>High Flex</li><li><strong>Midsole:</strong> NHP Ultra Rebound</li><li><strong>Sole:</strong> Rubber</li></ul>','DUNE Ultra Rebound Technology','Nubuck','assets/img/products/dune-stone.webp','20260723',NULL,1,0,'{"materialComposition":null,"weightGrams":555,"fit":"Relaxed","toeCap":"Composite (NHP)","midsole":null,"sole":"NHP Rubber","gender":"Unisex","season":"Winter","pageRef":67}'),
('dune-mount-occupational','footwear',5,'Dune Mount','Mid-cut occupational safety shoe with anti-abrasion mesh upper. 06 SR rated, suitable for general occupational use.','<p>The Dune Mount Occupational is designed for workers needing safety footwear at occupational level (06 SR) rather than full safety-shoe certification. It features the same anti-abrasion mesh upper found in the Dune safety range.</p><p>Certified to EN ISO 20347:2022+A1:2024, it provides slip resistance (SR) without a mandatory toecap, making it lighter and more comfortable for light-duty occupational use.</p>','DUNE Ultra Rebound Technology','Anti-Abrasion Mesh','assets/img/products/dune-mount-occupational.webp','20260723',NULL,1,0,'{"materialComposition":null,"weightGrams":null,"fit":"Relaxed","toeCap":null,"midsole":null,"sole":"NHP Rubber","gender":"Unisex","season":null,"pageRef":67}'),
('dune-micro','footwear',6,'Dune Micro','Low-cut S3S safety shoe with microfiber + TPU upper. Lightweight design for light to medium work environments.','<p>The new<strong> Dune Micro cushioned safety shoes</strong> are part of the<strong> new line of work shoes Kapriol - Ultra Rebound Technology </strong>designed to ensure maximum comfort in working environments. The special sole of the new work shoes, with <strong>special NHP compound midsole with Ultra Rebound effect</strong>, gives an immediate feeling of <strong>elasticity, softness and cushioning during walking. </strong></p><p>The innovative<strong> microfiber upper </strong>of the shoes Dune Micro guarantees the same strength of natural leather, maintaining the <strong>comfort and adaptability to the shape of the foot</strong> that offers this type of fabric. The pronounced carving and the appropriate drains, instead, facilitate the leakage of mud by keeping the sole always clean and adherent to the ground.</p><p>The <strong>Dune Micro work shoes</strong> are also equipped with taping that give the shoe a <strong>contemporary look</strong> and are available in both low-top and stocking version, in colors with yellow or gray details.</p><h3>TECHNICAL SPECIFICATIONS</h3><ul><li>Padding on the heel and malleolus</li><li>padded tongue</li><li>Upper in durable microfiber, without seams</li><li>rubber reinforcement on the toe</li><li>taping for a contemporary look</li><li>Weight: 460 gr. (tg. 42)</li><li>EN ISO 20345: 2022</li></ul><h3>Materials</h3><ul><li>Upper: Microfiber and TPU</li><li>Toe: Carbon fibre</li><li>Insole: NHP Tech</li><li>Anti-perforation insole: High Flex PS</li><li>Midsole: NHP Ultra Rebound</li><li>Sole: rubber sole</li></ul>','DUNE Ultra Rebound Technology','Microfiber + TPU','assets/img/products/dune-micro.webp','20260723',NULL,0,0,'{"materialComposition":null,"weightGrams":460,"fit":"Relaxed","toeCap":"Composite (NHP)","midsole":null,"sole":"NHP Rubber","gender":"Unisex","season":null,"pageRef":67}'),
('dune-micro-sock','footwear',7,'Dune Micro Sock','Low-cut safety shoe with sock-style microfiber + TPU upper for a snug, seamless fit. S3S FO SR certified.','<p>The <strong>safety shoes Dune Micro Sock</strong> are part of the <strong>new line of work shoes Dune - Ultra Rebound Technology, equipped with an innovative midsole with cushioning and movement return effect</strong>, which guarantees softness, flexibility and elasticity. Thanks to the <strong>midsole</strong> made with the <strong>special NHP </strong>(Nylon High Performances) compound composed of EVA, with the specific function of <strong>cushioning impacts on the foot</strong>, the work shoes Dune are particularly comfortable and performing, At the same time reducing the possibility of damage to joints and muscles.</p><p>The safety shoes Dune Micro Sock are characterized by the <strong>particular &quot;sock&quot; fit that wraps the foot like a sock</strong>, giving greater comfort and protection from entering dust and small debris in the shoe, In addition to the <strong>innovative microfiber upper</strong> that offers both strength and comfort given by the ability of the fabric to adapt to the shape of the foot. The<strong> pronounced carving of the sole </strong>and the appropriate drains facilitate the escape of mud, ensuring a clean and adherent to the ground.</p><h3>TECHNICAL SPECIFICATIONS</h3><ul><li>Uppers that wraps the foot and ankle</li><li>taping for a contemporary look</li><li>Upper in durable microfiber, without seams</li><li>rubber reinforcement on the toe</li><li>Weight: 490 gr. (tg. 42)</li><li>EN ISO 20345: 2022</li></ul><h3>MATERIALS</h3><ul><li>Upper: Microfiber and TPU</li><li>Toe: Carbon fibre</li><li>Insole: NHP Tech</li><li>Anti-perforation insole: High Flex PS</li><li>Midsole: NHP Ultra Rebound</li><li>Sole: rubber sole</li></ul>','DUNE Ultra Rebound Technology','Microfiber + TPU','assets/img/products/dune-micro-sock.webp','20260723',NULL,0,0,'{"materialComposition":null,"weightGrams":460,"fit":"Relaxed","toeCap":"Composite (NHP)","midsole":null,"sole":"NHP Rubber","gender":"Unisex","season":null,"pageRef":67}'),
('dune-occupational','footwear',8,'Dune Occupational','Low-cut occupational shoe (02 SR) with Jaquard + TPU upper. No mandatory toecap, lightweight for general occupational use.','<p>Dune Occupational are the <strong>new work and leisure shoes without toe of the line Kapriol Dune - Ultra Rebound Technology</strong>, designed to ensure a high daily comfort. Thanks to the <strong>innovative NHP and EVA compound midsole</strong>, the Dune work shoes have an<strong> Ultra Rebound effect</strong> that absorbs the impact on the foot during walking.</p><p>The Dune Occupational shoes have a <strong>seamless jaquard upper and TPU reinforcements</strong> that make them extremely <strong>comfortable and lightweight</strong>. In addition, the pronounced carving and the special drains of the sole, facilitate the escape of mud and materials, keeping it always clean and adherent to the ground.</p><p>The <strong>cushioned work shoes of the Dune line</strong> are footwear <strong>designed to be extremely lightweight and flexible</strong>, allowing the natural fold of the foot without offering resistance: The challenge won by the Dune shoes is to have balanced an optimal cushioning with a lightweight structure that guarantees comfort and support for the foot.</p><h3>TECHNICAL SPECIFICATIONS</h3><ul><li>taping for a contemporary look</li><li>Upper in durable microfiber, without seams</li><li>rubber reinforcement on the toe</li><li>Weight: 490 gr. (tg. 42)</li><li>EN ISO 20347: 2022</li></ul><h3>Materials</h3><ul><li>Upper: Jaquard</li><li>Midsole: NHP Ultra Rebound</li><li>Sole: Eva - PU - rubber</li></ul>','DUNE Ultra Rebound Technology','Jaquard + TPU','assets/img/products/dune-occupational.webp','20260723',NULL,0,0,'{"materialComposition":null,"weightGrams":null,"fit":"Relaxed","toeCap":null,"midsole":null,"sole":"NHP Rubber","gender":"Unisex","season":null,"pageRef":67}'),
('makalu','footwear',9,'Makalu Safety','Heavy-duty high-cut safety boot with nubuck upper. S7S HI CI WR HRO FO L6 SRC — maximum protection for extreme environments.','<p><strong>Makalu</strong> is the work boot that guarantees maximum impact and abrasion resistance. Ideal for <strong>heavy-duty work</strong> in hostile situations. These work boots are particularly <strong>resistant to cuts and wear </strong>thanks to the high <strong>upper thickness of 2.2 mm.</strong> The<strong> water-repellent inner membrane </strong>makes the work boot water-resistant even for prolonged use in wet or muddy environments.</p><p>The Makalu safety boots are <strong>manufactured in Italy</strong> and packed in top quality treated leathers. Inside they are lined with <strong>full-grain leather </strong>to give the safety shoe a comfortable fit.</p><p>The Makalu work boots are available both as safety work boots with a protective toe and in a version without a toe cap.</p><h3>TECHNICAL SPECIFICATIONS</h3><ul><li>EVA footbed with gel inserts for stability</li><li>anti-slip rubber sole with high grip padded rim and tongue with gusset that prevents the ingress of external materials</li><li>lightweight composite safety toe cap</li><li>high-strength metal hooks</li><li>full-grain nubuck leather upper - thickness 2.2 mm</li><li>protective edge in strong bonded and stitched rubber - thickness 1.5 mm</li></ul><h3>MATERIAL</h3><ul><li>Sole: rubber with EVA midsole</li><li>Toe cap: composite material</li><li>Upper: nubuck</li><li>Hooks: metal</li></ul>',NULL,'Nubuck','assets/img/products/makalu.webp','20260723',NULL,0,0,'{"materialComposition":null,"weightGrams":870,"fit":"Regular","toeCap":"Steel","midsole":"EVA","sole":"Rubber","gender":"Unisex","season":"Winter","pageRef":68}'),
('yosemite','footwear',10,'Yosemite','High-cut heavy-work safety boot with nubuck upper. S3L SR FO WR CI certified — cold and waterproof protection.','<p>The <strong>Yosemite</strong> work shoe is equipped with a durable <strong>composite toe-cap </strong>that provides total protection of the foot and also allows you to maintain a high level of <strong>insulation thermal</strong>.</p><p>The <strong>high flex anti-perforation insole</strong> has been designed to make work boots extremely safe and at the same time ensure maximum <strong>lightness and comfort.</strong> The <strong>high-thickness nubuck leather </strong>upper gives it a high <strong>resistance to cut and abrasion</strong> even in the most hostile situations. A special internal membrane makes the<strong> work boots waterproof,</strong> ideal for prolonged use in wet or muddy environments.</p><p>The <strong>high safety shoes Yosemite are certified S3L SR FO WR CI </strong>to ensure maximum professionalism and safety at work.</p><h3>TECHNICAL SPECIFICATIONS</h3><ul><li>self-cleaning non-slip grooves that ensure excellent grip on all surfaces</li><li>padded tongue and back edge for high comfort</li><li>high thickness full grain leather upper (mm.2)</li><li>rubber reinforcement on the toe</li><li>water-repellent inner membrane</li></ul><h3>MATERIALS</h3><p>Sole: PU PU</p><ul><li>Upper: Nabuk</li><li>Toe cap: composite material</li><li>Hooks: metal</li></ul>',NULL,'Nubuck','assets/img/products/yosemite.webp','20260723',NULL,0,0,'{"materialComposition":null,"weightGrams":740,"fit":"Relaxed","toeCap":"Composite (PU)","midsole":null,"sole":"PU","gender":"Unisex","season":"Winter","pageRef":68}'),
('spencer-low','footwear',11,'Spencer Low','Low-cut S3L ESD safety shoe with synthetic nubuck upper. Ideal for electronics and antistatic work environments.','<p>Innovative safety boot that stands out for its quality material and attractive design.Its light weight and comfort make it one of a kind. The internal EVA insole with gel inserts promote correct posture and guarantee fit stability, making it especially comfortable.</p>
