INSERT INTO `spec_code` (`spec_group`, `code`, `title`, `description`, `img`, `sort_order`) VALUES
('performance','A','A - Antistatic Shoe','Work shoes with antistatic properties that allow the controlled passage of low-voltage currents, dissipating the electrostatic charges accumulated by the operator during work activities and reducing the risk of ignition in environments with the presence of flammable or explosive substances.',NULL,0),
('performance','CI','CI - Cold insulation','Work shoes designed for outdoor use with exposure to atmospheric agents at low temperatures. The entire footwear is subjected to a specific test at −17 °C, verifying that the drop in internal temperature is not lower than the required standards, thus ensuring perfect maintenance of the foot''s thermal comfort.',NULL,1),
('performance','ESD','ESD - Electrostatic Discharge','Shoes that constantly discharge the static electricity accumulated by the human body to the ground, also protecting devices that are sensitive to electrostatic discharge.',NULL,2),
('performance','FO','FO - Resistance of the sole to hydrocarbons','Work shoes equipped with soles designed to resist prolonged contact with oily substances and hydrocarbons without undergoing structural alterations. The laboratory test involves immersing the compound in Trimethylpentane, verifying that the swelling and increase in volume of the sole do not exceed 12%, thus ensuring the stability and durability of the shoe over time. This requirement is mandatory for work footwear according to the 2011 standard, while it becomes additional and optional for the 2022 standard.','assets/img/certs/fo.webp',3),
('performance','GRIP','Non-slip sole','All Kapriol shoe soles are tested for conformity with the EN 20345:2011 Standard requirements concerning non-slip performance. 
